// 报价与提交复核同一原节点及当前处境；任何晚失败仍由Common和本账原子回滚。
#include "family_marriage_commands.hpp"
#include "succession_personal_assets.hpp"
#include <tuple>
namespace hanmo::resident {namespace {
// 所有命令参数固定字段，路径外的新权利字段不能悄悄变为默认许可。
bool shape(const FamilyMarriageCommand& c){auto id=[](const StableId& s){return !s.empty()&&s.size()<=256;};if(c.kind=="family_marriage_receive")return id(c.statement_id)&&c.proposal_id.empty()&&c.decision.empty()&&c.marriage_id.empty();if(c.kind=="family_marriage_reply")return c.statement_id.empty()&&id(c.proposal_id)&&(c.decision=="accepted"||c.decision=="refused"||c.decision=="withdrawn")&&c.marriage_id.empty();if(c.kind=="family_marriage_dissolve")return id(c.statement_id)&&id(c.marriage_id)&&c.proposal_id.empty()&&c.decision.empty();return false;}
// 精确命令绑定防止已报价的听取操作被替换成另一人的接受或解除。
bool same(const FamilyMarriageCommand& a,const FamilyMarriageCommand& b){return std::tie(a.kind,a.statement_id,a.proposal_id,a.decision,a.marriage_id)==std::tie(b.kind,b.statement_id,b.proposal_id,b.decision,b.marriage_id);}
// 完整当前世界戳包括恢复epoch；永久来源字段不能代替本次命令的新鲜度。
bool identity(const WorldIdentity& a,const WorldIdentity& b){return std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)==std::tie(b.world_id,b.execution_epoch,b.revision,b.tick);}
}
Outcome<FamilyMarriageCommand> decode_family_marriage_command(const StableId& kind,const BoundaryValue& v){try{using namespace boundary;auto unique=validate_succession_json_unique(v);if(!unique.ok)return {false,{},unique.error};FamilyMarriageCommand c;c.kind=kind;if(kind=="family_marriage_receive"){fields(v,{"statement_id"},{},kind);c.statement_id=get_string(v,"statement_id","");}else if(kind=="family_marriage_reply"){fields(v,{"proposal_id","decision"},{},kind);c.proposal_id=get_string(v,"proposal_id","");c.decision=get_string(v,"decision","");}else if(kind=="family_marriage_dissolve"){fields(v,{"statement_id","marriage_id"},{},kind);c.statement_id=get_string(v,"statement_id","");c.marriage_id=get_string(v,"marriage_id","");}else fail("UnknownFamilyMarriageCommand",kind);if(!shape(c))fail("InvalidFamilyMarriageCommand",kind);return {true,std::move(c),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<FamilyMarriageQuote> preview_family_marriage_command(const CommonStore& c,const FamilyState& family,const FamilyDeathState& death,const InteractionState& meeting,const InteractionCatalog& interaction,const InteractionAccess& contact,const MarriageSourceCatalog& catalog,const FamilyMarriageState& state,const MarriageAccess& access,const StableId& actor,const FamilyMarriageCommand& command){auto fail=[](const StableId& code)->Outcome<FamilyMarriageQuote>{return {false,{},common_failure(code).error};};if(!catalog.enabled)return fail("MarriageProfileRequired");if(!shape(command))return fail("InvalidFamilyMarriageCommand");const auto* who=c.actor(actor);if(actor!=c.state().metadata.player_actor_id||!who||!who->alive||!who->available||!who->action_id.empty())return fail("MarriageLivingDecisionMakerRequired");auto history=validate_family_marriage(c,family,death,interaction,catalog,state,access);if(!history.ok)return {false,{},history.error};if(!access.personally_available)return fail("MarriageAvailabilityHistoryRequired");auto free=access.personally_available(actor,c.tick(),{});if(!free.ok)return {false,{},free.error};FamilyMarriageQuote q{c.state().identity,command,{}};
    StableId statement=command.statement_id;if(command.kind=="family_marriage_reply"){const auto* p=state.proposals.find(command.proposal_id);if(!p)return fail("MarriageProposalRequired");if(history.value.replied_proposals.count(command.proposal_id))return fail("MarriageProposalAlreadyAnswered");const auto expected=command.decision=="withdrawn"?p->source.speaker_actor_id:p->source.listener_actor_id;if(actor!=expected)return fail("MarriagePersonalDecisionRequired");if(command.decision!="accepted")return {true,std::move(q),{}};statement=p->source.statement_id;}
    auto proof=preview_marriage_statement(c,meeting,interaction,contact,catalog,actor,statement);if(!proof.ok)return {false,{},proof.error};q.source=std::move(proof.value);const auto& original=q.source->statement;free=access.personally_available(original.speaker_actor_id,c.tick(),{});if(!free.ok)return {false,{},free.error};
    if(command.kind=="family_marriage_dissolve"){if(original.intent!="accept_dissolution")return fail("MarriageDissolutionConsentRequired");const auto* bond=history.value.active_by_actor.find(actor);if(!bond||bond->authored_origin||bond->id!=command.marriage_id||!((bond->first_actor_id==actor&&bond->second_actor_id==original.speaker_actor_id)||(bond->second_actor_id==actor&&bond->first_actor_id==original.speaker_actor_id)))return fail("MarriageDissolutionBondMismatch");}
    else{if(original.intent!="offer_marriage")return fail("MarriageOfferRequired");if(command.kind=="family_marriage_reply"){auto eligible=validate_marriage_current_pair(catalog,history.value,original.speaker_actor_id,original.listener_actor_id);if(!eligible.ok)return {false,{},eligible.error};}else for(const auto& row:state.proposals.rows())if(row.second.source.statement_id==statement)return fail("MarriageProposalAlreadyReceived");}
    return {true,std::move(q),{}};
}
Outcome<FamilyEffect> apply_family_marriage_command(CommonStore& c,const FamilyState& family,const FamilyDeathState& death,const InteractionState& meeting,const InteractionCatalog& interaction,const InteractionAccess& contact,const MarriageSourceCatalog& catalog,FamilyMarriageState& state,const MarriageAccess& access,const StableId& actor,const FamilyMarriageCommand& command,const FamilyMarriageQuote& quote){if(!same(command,quote.command)||!identity(c.state().identity,quote.identity))return {false,{},common_failure("StaleMarriageQuote").error};auto fresh=preview_family_marriage_command(c,family,death,meeting,interaction,contact,catalog,state,access,actor,command);if(!fresh.ok)return {false,{},fresh.error};if(bool(fresh.value.source)!=bool(quote.source)||(quote.source&&!marriage_statement_equal(fresh.value.source->statement,quote.source->statement)))return {false,{},common_failure("MarriageQuoteSourceChanged").error};Outcome<StableId> result;if(command.kind=="family_marriage_receive")result=receive_marriage_proposal(c,family,death,meeting,interaction,contact,catalog,state,access,*fresh.value.source);else if(command.kind=="family_marriage_reply")result=reply_marriage_proposal(c,family,death,meeting,interaction,contact,catalog,state,access,command.proposal_id,command.decision,fresh.value.source);else result=dissolve_personal_marriage(c,family,death,meeting,interaction,contact,catalog,state,access,command.marriage_id,*fresh.value.source);if(!result.ok)return {false,{},result.error};FamilyEffect receipt;receipt.success=true;receipt.actor_id=actor;receipt.player_actor_id=actor;receipt.fact_id=result.value;return {true,std::move(receipt),{}};}
BoundaryValue encode_family_marriage_quote(const FamilyMarriageQuote& quote){using V=BoundaryValue;V::Dict out{{"ok",V{true}},{"duration",V{Integer{0}}},{"kind",V{quote.command.kind}},{"decision",V{quote.command.decision}},{"scope",V{"personal_marriage_separate_assets"}},{"money",V{Integer{0}}}};if(quote.source)out.emplace_back("other_actor_id",V{quote.source->statement.speaker_actor_id});return V{std::move(out)};}
Status validate_family_marriage_receipt(const FamilyMarriageState& state,const StableId& kind,const StableId& actor,Integer tick,const FamilyEffect& r){if(r.success!=std::optional<bool>{true}||r.actor_id!=std::optional<StableId>{actor}||r.player_actor_id!=r.actor_id||!r.fact_id||r.already_completed||r.code||r.heir_actor_id)return common_failure("InvalidMarriageReceipt");if(kind=="family_marriage_receive"){const auto* p=state.proposals.find(*r.fact_id);return p&&p->source.listener_actor_id==actor&&p->source.tick==tick?common_success():common_failure("MarriageReceiptSourceMismatch");}if(kind=="family_marriage_reply"){const auto* p=state.replies.find(*r.fact_id);return p&&p->actor_id==actor&&p->tick==tick?common_success():common_failure("MarriageReceiptSourceMismatch");}if(kind=="family_marriage_dissolve"){const auto* p=state.dissolutions.find(*r.fact_id);return p&&p->source.listener_actor_id==actor&&p->source.tick==tick?common_success():common_failure("MarriageReceiptSourceMismatch");}return common_failure("UnknownFamilyMarriageCommand");}
}
